function creerFilePriorite() {
  const heap = [];

  function parent(i) { return Math.floor((i - 1) / 2); }
  function gauche(i) { return 2 * i + 1; }
  function droite(i) { return 2 * i + 2; }

  function echanger(i, j) {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  }

  function remonter(i) {
    while (i > 0 && heap[parent(i)].priorite > heap[i].priorite) {
      echanger(i, parent(i));
      i = parent(i);
    }
  }

  function descendre(i) {
    let min = i;
    const g = gauche(i);
    const d = droite(i);
    if (g < heap.length && heap[g].priorite < heap[min].priorite) min = g;
    if (d < heap.length && heap[d].priorite < heap[min].priorite) min = d;
    if (min !== i) {
      echanger(i, min);
      descendre(min);
    }
  }

  return {
    enqueue(val, priorite) {
      const element = { val, priorite };
      heap.push(element);
      remonter(heap.length - 1);
    },
    dequeue() {
      if (heap.length === 0) return undefined;
      const min = heap[0];
      const dernier = heap.pop();
      if (heap.length > 0) {
        heap[0] = dernier;
        descendre(0);
      }
      return min.val;
    },
    taille() {
      return heap.length;
    }
  };
}
```

