function creerSubject() {
  const abonnes = [];
  let estComplete = false;

  return {
    next(val) {
      if (estComplete) return;
      abonnes.forEach(a => a.next && a.next(val));
    },
    error(err) {
      if (estComplete) return;
      abonnes.forEach(a => a.error && a.error(err));
    },
    complete() {
      if (estComplete) return;
      estComplete = true;
      abonnes.forEach(a => a.complete && a.complete());
      abonnes.length = 0;
    },
    subscribe({ next, error, complete }) {
      const abonne = { next, error, complete };
      abonnes.push(abonne);
      return {
        unsubscribe() {
          const idx = abonnes.indexOf(abonne);
          if (idx !== -1) abonnes.splice(idx, 1);
        }
      };
    }
  };
}
