function dijkstra(graphe, depart) {
  const distances = {};
  const visites = new Set();

  for (const noeud of Object.keys(graphe)) {
    distances[noeud] = Infinity;
  }
  distances[depart] = 0;

  while (true) {
    let minNoeud = null;
    let minDist = Infinity;
    for (const noeud of Object.keys(distances)) {
      if (!visites.has(noeud) && distances[noeud] < minDist) {
        minDist = distances[noeud];
        minNoeud = noeud;
      }
