    if (minNoeud === null) break;
    visites.add(minNoeud);

    const voisins = graphe[minNoeud] || {};
    for (const [voisin, poids] of Object.entries(voisins)) {
      const nouvelleDist = distances[minNoeud] + poids;
      if (nouvelleDist < (distances[voisin] ?? Infinity)) {
